import { useRoute } from 'vue-router';
import { onMounted, watch } from 'vue';
import { useAssetPrototypeStore } from '../../../stores/assetPrototype.js';

const route = useRoute();
const store = useAssetPrototypeStore();

const tabs = [
  { label: 'Overview', value: 'overview' },
  { label: 'Realized', value: 'realized' },
  { label: 'Risk', value: 'risk' },
];
const riskOptions = ['All', 'Low', 'Medium', 'High'];

onMounted(() => {
  if (route.query.tab) {
    store.setPnlTab(String(route.query.tab));
  }
});

watch(() => store.activePnlTab, (tab) => {
  if (tab === 'risk') {
    store.setRiskFilter('High');
  }
});

styleBlocks:
.pnl-page {
  background:
    linear-gradient(180deg, rgba(22, 133, 91, 0.12), rgba(238, 243, 248, 0) 260px),
    var(--pb-bg);
}

.tab-bar {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-bottom: 14px;
  padding: 4px;
  border: 1px solid var(--pb-border);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.78);
}

.tab-button {
  min-height: 34px;
  border-radius: 7px;
  background: transparent;
  color: var(--pb-muted);
  font-size: 13px;
  font-weight: 800;
}

.tab-button.active {
  background: var(--pb-primary);
  color: #ffffff;
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.metric-card {
  padding: 14px;
}

.metric-card span {
  display: block;
  color: var(--pb-muted);
  font-size: 12px;
}

.metric-card strong {
  display: block;
  margin-top: 8px;
  font-size: 21px;
}

.metric-card small {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  font-weight: 800;
}

.trend-panel,
.record-panel {
  margin-top: 12px;
  padding: 16px;
}

.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.section-heading h2 {
  margin: 0;
  font-size: 17px;
}

.section-heading p {
  margin: 3px 0 0;
  color: var(--pb-muted);
  font-size: 12px;
}

.trend-chart {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  align-items: end;
  gap: 8px;
  height: 132px;
  margin-top: 16px;
  padding: 12px;
  border-radius: 8px;
  background: var(--pb-surface-soft);
}

.trend-bar {
  min-height: 18px;
  border-radius: 6px 6px 3px 3px;
  background: linear-gradient(180deg, #176b87, #48a6a7);
}

.record-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid var(--pb-border);
  cursor: pointer;
}

.record-row:last-child {
  border-bottom: 0;
}

.record-row strong,
.record-row span {
  display: block;
}

.record-row span,
.record-value span {
  margin-top: 4px;
  color: var(--pb-muted);
  font-size: 12px;
}

.record-value {
  text-align: right;
}

.loading-state,
.empty-state {
  padding: 26px 0;
  color: var(--pb-muted);
  text-align: center;
}

.sheet-backdrop {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 14px;
  background: rgba(20, 30, 42, 0.42);
}

.filter-sheet,
.detail-sheet {
  width: min(100%, 398px);
  padding: 16px;
}

.sheet-option {
  width: 100%;
  min-height: 44px;
  margin-top: 8px;
  border: 1px solid var(--pb-border);
  border-radius: 8px;
  background: var(--pb-surface);
  color: var(--pb-text);
  font-weight: 800;
  text-align: left;
  padding: 0 14px;
}

.sheet-option.active {
  border-color: var(--pb-primary);
  background: var(--pb-primary-soft);
  color: var(--pb-primary);
}

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 16px 0;
}

.detail-grid div {
  padding: 12px;
  border-radius: 8px;
  background: var(--pb-surface-soft);
}

.detail-grid dt {
  color: var(--pb-muted);
  font-size: 12px;
}

.detail-grid dd {
  margin: 5px 0 0;
  font-weight: 800;
}
